package com.studenthub.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.studenthub.dao.PrivateMessageDAO;import com.studenthub.model.PrivateMessage;import com.studenthub.util.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet(name="SendPrivateMessageServlet",urlPatterns="/messages/send") @MultipartConfig(maxFileSize=20971520L,maxRequestSize=22000000L)
public class SendPrivateMessageServlet extends HttpServlet{
 private final PrivateMessageDAO dao=new PrivateMessageDAO();private final ObjectMapper json=new ObjectMapper();
 @Override protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException,jakarta.servlet.ServletException{q.setCharacterEncoding("UTF-8");if(!CsrfToken.isValid(q)){r.sendError(403);return;}long conversation;try{conversation=Long.parseLong(q.getParameter("conversationId"));}catch(Exception e){r.sendError(400);return;}String content=q.getParameter("message");AttachmentRequest.Result file=AttachmentRequest.read(q.getPart("attachment"));if(!file.valid()){jsonError(r,400,file.error());return;}if((content==null||content.isBlank())&&file.upload()==null){jsonError(r,400,"Type a message or choose an attachment.");return;}try{PrivateMessage m=dao.send(conversation,(Long)q.getSession().getAttribute("userId"),q.getParameter("clientMessageId"),content,file.upload());r.setContentType("application/json");r.setCharacterEncoding("UTF-8");json.writeValue(r.getWriter(),Map.of("messageId",m.messageId(),"createdLabel",m.getCreatedLabel()));}catch(SecurityException e){AttachmentRequest.discard(file.upload());r.sendError(403);}catch(IllegalArgumentException e){AttachmentRequest.discard(file.upload());jsonError(r,400,e.getMessage());}catch(Exception e){AttachmentRequest.discard(file.upload());getServletContext().log("Private send failed: "+e.getClass().getName());jsonError(r,500,"Failed to send");}}
 private void jsonError(HttpServletResponse r,int status,String message)throws IOException{r.setStatus(status);r.setContentType("application/json");json.writeValue(r.getWriter(),Map.of("error",message));}
}
